-- ContosoBikesDW: the Contoso Bikes star schema of episode 1, as a SQL Server database (generated by tools/make_sql.py, do not edit).
-- Run on the lab SQL Server (SQL Server 2022 Developer, default instance), connected to master. Fictional data only.
IF DB_ID(N'ContosoBikesDW') IS NOT NULL
BEGIN
    ALTER DATABASE [ContosoBikesDW] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [ContosoBikesDW];
END
GO
CREATE DATABASE [ContosoBikesDW];
GO
ALTER DATABASE [ContosoBikesDW] SET RECOVERY SIMPLE;   -- the scale-up script inserts about two million rows
GO
USE [ContosoBikesDW];
GO
CREATE TABLE dbo.DimDate (
    Date date NOT NULL,
    Year int NOT NULL,
    Quarter char(2) NOT NULL,
    MonthNumber int NOT NULL,
    Month char(3) NOT NULL,
    YearMonth char(7) NOT NULL,
    YearMonthNumber int NOT NULL,
    DayofWeekNumber int NOT NULL,
    DayofWeek char(3) NOT NULL,
    CONSTRAINT PK_DimDate PRIMARY KEY (Date)
);
GO
CREATE TABLE dbo.DimProduct (
    ProductKey int NOT NULL,
    ProductCode varchar(20) NOT NULL,
    Product varchar(60) NOT NULL,
    Subcategory varchar(40) NOT NULL,
    Category varchar(40) NOT NULL,
    Color varchar(20) NOT NULL,
    CONSTRAINT PK_DimProduct PRIMARY KEY (ProductKey)
);
GO
CREATE TABLE dbo.DimCustomer (
    CustomerKey int NOT NULL,
    CustomerCode varchar(10) NULL,
    Customer varchar(80) NOT NULL,
    City varchar(40) NOT NULL,
    Country varchar(40) NOT NULL,
    CONSTRAINT PK_DimCustomer PRIMARY KEY (CustomerKey)
);
GO
CREATE TABLE dbo.DimStore (
    StoreKey int NOT NULL,
    Store varchar(40) NOT NULL,
    Country varchar(40) NOT NULL,
    Channel varchar(20) NOT NULL,
    CONSTRAINT PK_DimStore PRIMARY KEY (StoreKey)
);
GO
CREATE TABLE dbo.FactSales (
    OrderNumber varchar(20) NOT NULL,
    LineNumber int NOT NULL,
    OrderDate date NOT NULL,
    ShipDate date NOT NULL,
    CustomerKey int NOT NULL,
    ProductKey int NOT NULL,
    StoreKey int NOT NULL,
    Quantity int NOT NULL,
    UnitPrice decimal(10,2) NOT NULL,
    UnitCost decimal(10,2) NOT NULL,
    LineAmount AS CONVERT(decimal(18,2), Quantity * UnitPrice) PERSISTED,
    LineCost AS CONVERT(decimal(18,2), Quantity * UnitCost) PERSISTED,
    CONSTRAINT PK_FactSales PRIMARY KEY (OrderNumber, LineNumber),
    CONSTRAINT FK_FactSales_DimCustomer FOREIGN KEY (CustomerKey) REFERENCES dbo.DimCustomer (CustomerKey),
    CONSTRAINT FK_FactSales_DimProduct FOREIGN KEY (ProductKey) REFERENCES dbo.DimProduct (ProductKey),
    CONSTRAINT FK_FactSales_DimStore FOREIGN KEY (StoreKey) REFERENCES dbo.DimStore (StoreKey),
    CONSTRAINT FK_FactSales_DimDate FOREIGN KEY (OrderDate) REFERENCES dbo.DimDate (Date)
);
GO
